/* audio/effects/bake.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../../context.js";

export function install(P) {


  async function renderTrackToWav(url, settings) {
    const OfflineContext = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    if (!OfflineContext) return null;
    const source = await P.decodeTrack(url);
    if (!source) return null;
    const reverbTail = settings.fx.reverbEnabled
      ? P.clamp(Number(settings.fx.reverbDecay) || P.FX_RANGES.reverbDecay.fallback,
        P.FX_RANGES.reverbDecay.min, P.FX_RANGES.reverbDecay.max)
      : 0;
    const feedback = settings.fx.delayEnabled
      ? P.clamp(Number(settings.fx.delayFeedback) || 0, P.FX_RANGES.delayFeedback.min, P.FX_RANGES.delayFeedback.max)
      : 0;
    const delayTail = feedback > 0
      ? Math.min(4, P.clamp(Number(settings.fx.delayTime) || P.FX_RANGES.delayTime.fallback,
        P.FX_RANGES.delayTime.min, P.FX_RANGES.delayTime.max) * feedback / (1 - feedback))
      : 0;
    const tail = reverbTail + delayTail;
    const length = source.length + Math.ceil(tail * source.sampleRate) + 1;
    const context = new OfflineContext(source.numberOfChannels, length, source.sampleRate);
    const input = context.createBufferSource();
    input.buffer = source;
    P.connectOfflineFxChain(context, input, context.destination, settings);
    input.start(0);
    const rendered = await context.startRendering();
    // The WAV encoder is loaded on first render, not at boot.
    return await P.encodeWav(rendered);
  }

  // Keep the blob cache bounded: a rendered long track is many megabytes.
  function rememberRenderedTrack(source, key, url) {
    const id = P.renderKey(source, key);
    const previous = P.renderedTrackCache.get(id);
    if (previous) window.setTimeout(() => URL.revokeObjectURL(previous.url), 8000);
    P.renderedTrackCache.delete(id);
    P.renderedTrackCache.set(id, { source, key, url });
    while (P.renderedTrackCache.size > P.MAX_RENDERED_TRACKS) {
      const [oldId, old] = P.renderedTrackCache.entries().next().value;
      P.renderedTrackCache.delete(oldId);
      // A crossfade copy may still be reading the old blob, so delay revocation.
      window.setTimeout(() => URL.revokeObjectURL(old.url), 8000);
    }
  }

  function ensureRenderedTrack(track) {
    const source = P.sourceUrl(track);
    if (!source || !P.anyFxEnabled()) return Promise.resolve(false);
    const settings = P.fxSnapshot();
    const key = JSON.stringify(settings.fx);
    const id = P.renderKey(source, key);
    if (P.renderedTrackCache.has(id)) return Promise.resolve(true);
    const pending = P.renderRequests.get(id);
    if (pending) return pending;

    const promise = P.renderTrackToWav(source, settings).then((blob) => {
      if (!blob) return false;
      P.rememberRenderedTrack(source, key, URL.createObjectURL(blob));
      return true;
    }).catch(() => false).finally(() => {
      if (P.renderRequests.get(id) === promise) P.renderRequests.delete(id);
    });
    P.renderRequests.set(id, promise);
    return promise;
  }

  function fxStatusText(active, failed) {
    if (active) return P.pt("effectRendering");
    if (failed) return P.pt("effectUnavailable");
    const left = Math.max(0, Math.ceil((P.fxRenderDeadline - Date.now()) / 1000));
    if (P.fxRenderDeadline && left > 0) return P.pt("effectCountdown", { s: left });
    if (P.isTrackRendered(P.state.current)) return P.pt("effectReady");
    return P.pt("effectLive", { s: Math.ceil(P.bakeDelayMs() / 1000) });
  }

  function setFxRendering(active, failed = false) {
    if (!active) P.fxRenderFailed = !!failed;
    const enabled = P.anyFxEnabled();
    document.querySelectorAll("[data-fx-status]").forEach((el) => {
      // Keep the warning visible after a failed render: the checkbox is on,
      // but the audible source is deliberately still the untouched original.
      el.hidden = !active && !enabled && !P.fxRenderFailed;
      el.textContent = P.fxStatusText(active, failed);
      el.classList.toggle("is-active", !!active);
      el.classList.toggle("is-unavailable", !active && !!failed);
    });
  }

  function startFxCountdown() {
    if (P.fxStatusTick) return;
    P.fxStatusTick = window.setInterval(() => {
      if (P.fxRenderDeadline && P.fxRenderDeadline <= Date.now()) {
        P.stopFxCountdown();
        return;
      }
      P.setFxRendering(false, P.fxRenderFailed);
    }, 500);
  }

  function stopFxCountdown() {
    if (!P.fxStatusTick) return;
    window.clearInterval(P.fxStatusTick);
    P.fxStatusTick = 0;
  }

  // One render per settled settings change. The original file plays through
  // the live effect chain meanwhile; the WAV only replaces it when ready.
  function requestFxRender() {
    if (P.fxRenderTimer) window.clearTimeout(P.fxRenderTimer);
    P.fxRenderToken++;
    const token = P.fxRenderToken;
    const delay = P.bakeDelayMs();
    P.fxRenderDeadline = Date.now() + delay;
    P.fxRenderFailed = false;
    P.setFxRendering(false, false);
    P.startFxCountdown();
    P.fxRenderTimer = window.setTimeout(async () => {
      P.fxRenderTimer = 0;
      P.fxRenderDeadline = 0;
      P.stopFxCountdown();
      const track = P.state.current;
      if (!track) { P.setFxRendering(false); return; }
      const wasPlaying = !P.audio.paused;
      const position = P.audio.currentTime || 0;
      P.setFxRendering(true);
      const baked = P.anyFxEnabled() ? await P.ensureRenderedTrack(track) : true;
      if (token !== P.fxRenderToken || P.state.current !== track) return;
      P.setFxRendering(false, !baked);
      P.loadCurrent({ autoplay: wasPlaying, startTime: position, fadeIn: false });
    }, delay);
  }

  function applyFxState() {
    P.syncFxVisual();
    // Slider movement is heard immediately; baking happens after the idle
    // delay. Both paths read the same persisted state.
    P.syncLiveFx();
    if (!P.anyFxEnabled()) {
      P.fxRenderDeadline = 0;
      P.stopFxCountdown();
      P.setFxRendering(false, false);
    }
    // loadCurrent() already waits for the first render during restore.
    if (!P.restoring) P.requestFxRender();
  }

  function applyBakeDelay(raw) {
    P.state.fxBakeDelayMs = P.normalizeBakeDelay(raw);
    // Re-arm an already pending bake so the visible countdown matches the
    // newly chosen idle time.
    if (P.fxRenderTimer) P.requestFxRender();
    else P.setFxRendering(false, P.fxRenderFailed);
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function setFxEnabled(kind, enabled) {
    if (!P.FX_KINDS.includes(kind)) return;
    P.state[`${kind}Enabled`] = !!enabled;
    P.applyFxState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function applyFxSetting(key, raw) {
    const range = P.FX_RANGES[key];
    if (!range) return;
    const value = Number(raw);
    P.state[key] = Number.isFinite(value) ? P.clamp(value, range.min, range.max) : range.fallback;
    P.applyFxState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }
  Object.assign(P, { renderTrackToWav, rememberRenderedTrack, ensureRenderedTrack, fxStatusText, setFxRendering, startFxCountdown, stopFxCountdown, requestFxRender, applyFxState, applyBakeDelay, setFxEnabled, applyFxSetting });
}
